"""Verified 1405 movable holidays; stable Solar Hijri observances in other years."""
import jdatetime
SOURCE='https://calendar.ut.ac.ir/documents/2139738/7092644/Calendar-1405.pdf/64228cbb-f4de-dc32-4d2b-57db3c8e322f?t=1761972997587'
FIXED={(1,1):'نوروز',(1,2):'نوروز',(1,3):'نوروز',(1,4):'نوروز',(1,12):'روز جمهوری اسلامی',(1,13):'روز طبیعت',(3,14):'رحلت امام خمینی',(3,15):'قیام پانزده خرداد',(11,22):'پیروزی انقلاب اسلامی',(12,29):'ملی شدن صنعت نفت'}
MOVABLE_1405={(1,1):'عید فطر',(1,2):'تعطیل عید فطر',(1,25):'شهادت امام جعفر صادق',(3,6):'عید قربان',(3,14):'عید غدیر',(4,3):'تاسوعا',(4,4):'عاشورا',(5,13):'اربعین',(5,21):'رحلت پیامبر و شهادت امام حسن',(5,22):'شهادت امام رضا',(5,30):'شهادت امام حسن عسکری',(6,8):'میلاد پیامبر و امام جعفر صادق',(8,22):'شهادت حضرت فاطمه',(10,2):'میلاد امام علی',(10,16):'مبعث پیامبر',(11,4):'میلاد امام مهدی',(12,9):'شهادت امام علی',(12,19):'عید فطر',(12,20):'تعطیل عید فطر'}
PERSIAN=[(1,6,'زادروز زرتشت'),(2,1,'بزرگداشت سعدی'),(2,10,'روز ملی خلیج فارس'),(2,12,'روز معلم'),(2,25,'بزرگداشت فردوسی و زبان فارسی'),(2,28,'بزرگداشت خیام'),(3,3,'آزادسازی خرمشهر'),(3,27,'روز جهاد کشاورزی'),(4,10,'روز صنعت و معدن'),(4,14,'روز قلم'),(4,22,'روز فناوری اطلاعات'),(4,25,'روز بهزیستی و تأمین اجتماعی'),(5,8,'بزرگداشت سهروردی'),(5,9,'روز اهدای خون'),(5,17,'روز خبرنگار'),(6,1,'روز پزشک'),(6,4,'روز کارمند'),(6,5,'روز داروسازی'),(6,13,'بزرگداشت ابوریحان بیرونی'),(6,21,'روز سینما'),(6,27,'روز شعر و ادب فارسی'),(7,1,'روز پرچم'),(7,7,'روز آتش‌نشانی و ایمنی'),(7,8,'بزرگداشت مولوی'),(7,20,'بزرگداشت حافظ'),(7,26,'روز تربیت بدنی و ورزش'),(7,29,'روز صادرات'),(8,13,'روز دانش‌آموز'),(8,14,'روز فرهنگ عمومی'),(8,24,'روز کتاب و کتاب‌خوانی'),(9,7,'روز نیروی دریایی'),(9,16,'روز دانشجو'),(9,25,'روز پژوهش'),(9,30,'شب یلدا'),(10,5,'روز ایمنی در برابر زلزله'),(11,19,'روز نیروی هوایی'),(11,29,'روز اقتصاد مقاومتی و کارآفرینی'),(12,5,'روز مهندسی'),(12,15,'روز درختکاری'),(12,25,'بزرگداشت پروین اعتصامی')]

def iran_on_date(day):
    jd=jdatetime.date.fromgregorian(date=day);key=(jd.month,jd.day);items=[]
    if key in FIXED:items.append(dict(title=FIXED[key],date=day,source=SOURCE,kind='شمسی',holiday=True))
    if jd.year==1405 and key in MOVABLE_1405:items.append(dict(title=MOVABLE_1405[key],date=day,source=SOURCE,kind='رسمی ۱۴۰۵',holiday=True))
    items.extend(dict(title=t,date=day,source=SOURCE,kind='شمسی',holiday=False) for m,d,t in PERSIAN if key==(m,d))
    return items

def day_off(day):
    return day.weekday() in (3,4) or any(x['holiday'] for x in iran_on_date(day))
